var o=[{title:`Posibles sustitutos`,text:`Una mochila cerrada con el contenido repartido de forma uniforme puede añadir resistencia a una sentadilla o a un paseo con carga. Las botellas de agua sirven como pesas ligeras de mano, y un escalón resistente puede sustituir una plataforma de ejercicio baja. Estos objetos no tienen un tamaño estándar ni marcas de peso, así que la carga y el equilibrio pueden cambiar sin avisar.`},{title:`El mobiliario es un riesgo importante`,text:`Una silla de comedor puede deslizarse o volcar durante fondos, step-ups o flexiones inclinadas, y muchas mesas no pueden soportar un remo con el peso corporal tirando desde debajo del borde. Nunca des por hecho que una mesa normal, una toalla, el pomo de una puerta o una estantería pueden aguantar el peso de tu cuerpo. Si una instalación depende de una fuerza o de un anclaje de los que no estás seguro, elige otro ejercicio.`},{title:`Revisa cada objeto`,text:`Asegúrate de que la superficie no resbale, de que el recipiente no gotee ni tenga asas rotas y de que las correas de la mochila no se estén rompiendo. Reparte el peso para que no se balancee de repente. Evita los recipientes de cristal, los bordes metálicos afilados y las pilas de libros sueltos. Entrena en un suelo despejado, lejos de cualquier cosa que pueda romperse.`},{title:`Progresa despacio`,text:`Empieza con un movimiento sencillo y una carga pequeña. Las repeticiones lentas y repetibles son mejores que los equilibrios complicados. Si no puedes pesar el objeto de forma fiable, anota la configuración y una idea aproximada de la resistencia en lugar de un número preciso. Mantén cada aumento lo bastante pequeño como para seguir teniendo el control.`},{title:`Cómo usar TrainUp`,text:`Un objeto doméstico no es un banco, un rack, una barra de dominadas ni una estación de poleas. En Perfil, indica un tipo de banco o una barra de dominadas solo para el equipamiento real. Cuando no puedas estar seguro de que un mueble es seguro, elige ejercicios con el peso corporal que no necesiten apoyo.`}];var n=[{label:`Mayo Clinic: seguridad y técnica en el entrenamiento con pesas`,url:`https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/weight-training/art-20045842`},{label:`Biblioteca de ejercicios de ACE`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`Declaración de posición del ACSM de 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var s={sections:o,sources:n};export{s as default,o as sections,n as sources};